mapper.select:
SELECT workspace_id FROM attachment FORCE INDEX (idx_attachment_workspace)
WHERE workspace_id > #{afterId} AND workspace_id <= #{throughId}
ORDER BY workspace_id LIMIT 1

mapper.update:
UPDATE attachment SET scan_state = #{state}, scan_engine = 'ClamAV',
  scan_database_version = #{version}, scan_signature = #{signature},
  scanned_at = UTC_TIMESTAMP(6), scan_expires_at = #{expiresAt},
  scan_owner = NULL, scan_lease_until = NULL, scan_next_attempt_at = #{expiresAt}
WHERE workspace_id = #{workspaceId} AND url = #{url} AND scan_owner = #{owner}
  AND scan_state = 'scanning' AND scan_lease_until > UTC_TIMESTAMP(6)

UPDATE attachment SET scan_state = 'clean', scan_engine = 'ClamAV',
  scan_database_version = #{report.databaseVersion}, scan_signature = #{report.signature},
  scanned_at = UTC_TIMESTAMP(6), scan_expires_at = #{expiresAt},
  scan_attempts = scan_attempts + 1, scan_last_attempt_at = UTC_TIMESTAMP(6), scan_owner = NULL, scan_lease_until = NULL,
  scan_next_attempt_at = #{expiresAt}
WHERE workspace_id = #{workspaceId} AND id = #{id}
